                        relationshipGain += evtChoices[k].relationship;
                        complianceGain += evtChoices[k].compliance;
                        break;
                    }
                }
            }

            state.domainState.budget -= totalCost;
            state.domainState.totalCost += totalCost;
            state.domainState.detection = Math.max(0, Math.min(100, state.domainState.detection + detectionGain));
            state.domainState.integrity = Math.max(0, Math.min(100, state.domainState.integrity + integrityGain));
            state.domainState.relationship = Math.max(0, Math.min(100, state.domainState.relationship + relationshipGain));
            state.domainState.compliance = Math.max(0, Math.min(100, state.domainState.compliance + complianceGain));

            var repDelta = Math.round((detectionGain * 0.35 + integrityGain * 0.25 + relationshipGain * 0.2 + complianceGain * 0.2) * 0.3);
            state.domainState.reputation = Math.max(0, Math.min(100, state.domainState.reputation + repDelta));

            state.domainState.detectionHistory.push(state.domainState.detection);
            state.domainState.integrityHistory.push(state.domainState.integrity);
            state.domainState.relationshipHistory.push(state.domainState.relationship);
            state.domainState.complianceHistory.push(state.domainState.compliance);
            state.domainState.reputationHistory.push(state.domainState.reputation);
            state.domainState.budgetHistory.push(state.domainState.budget);

            var results = {
                period: state.currentPeriod,
                roundName: round.title,
                cost: totalCost,
                detection: state.domainState.detection,
                integrity: state.domainState.integrity,
                relationship: state.domainState.relationship,
                compliance: state.domainState.compliance,
                reputation: state.domainState.reputation,
                budget: state.domainState.budget
            };

            // FIX v1.1.0: the engine increments currentPeriod to N+1 synchronously after
            // calculateResults returns; reading state.currentPeriod+1 here rendered N+2, rebuilding
            // the decision panel for round N+2. validateDecisions for the real round N+1 then could
            // not find its decision selects -> missing_decision -> DEAD-END. Render the completed
            // period + 1, and only on the live state (competition preview runs calc on a deep clone).
            var self = this;
            var _cp = state.currentPeriod;
            var _isLiveState = (typeof window !== 'undefined' && window.mySimulation && state === window.mySimulation.state);
            if (_isLiveState) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: _cp + 1 });
                }, 500);
            }

            return results;
        }

        _bindUndo() {
            /* an undo puts the period back but nothing redrew the round panel: the next round questions
               stayed on screen and the round being replayed could not be submitted. Redraw the round the
               framework now stands on, then let the shared guard register the new controls at once, so
               the same choices resubmitted replay the round exactly */
            if (this._undoBound || !window.mySimulation) return;
            var bus = window.mySimulation.eventBus;
            if (!bus || typeof bus.on !== 'function') return;
            this._undoBound = true;
            var self = this;
            bus.on('period:undone', function() {
                var st = window.mySimulation && window.mySimulation.state;
                if (!st) return;
                self._updateBriefing(st);
                try { if (typeof __eqilGuard !== 'undefined' && __eqilGuard && typeof __eqilGuard.pass === 'function') { __eqilGuard.pass(); } } catch (e) {}
            });
        }

