        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var weighted = Math.round(
                (r.detection || 0) * 0.35 +
                (r.integrity || 0) * 0.25 +
                (r.relationship || 0) * 0.2 +
                (r.compliance || 0) * 0.2
            );

            var performance = 'Needs Improvement';
            if (weighted >= 80) performance = 'Excellent ESG Auditor';
            else if (weighted >= 70) performance = 'Strong Auditor';
            else if (weighted >= 60) performance = 'Competent Auditor';

            var insights = [];
            if ((r.detection || 0) >= 70) insights.push('Strong forensic detection capability — you identified key greenwashing patterns.');
            else insights.push('Detection gaps remain — deeper forensic procedures would have revealed more.');
            if ((r.integrity || 0) >= 70) insights.push('High professional integrity maintained under pressure.');
            else insights.push('Professional integrity was compromised by business pressures in some rounds.');
            if ((r.relationship || 0) >= 50) insights.push('Client relationship managed effectively despite audit friction.');
            else insights.push('Client relationship deteriorated significantly — consider balancing rigor with diplomacy.');
            if ((r.compliance || 0) >= 70) insights.push('Regulatory compliance approach is well-aligned with EU Green Claims Directive.');
            else insights.push('Regulatory compliance gaps could expose ClearView to enforcement action.');

            return {
                overallScore: weighted,
                detection: r.detection,
                integrity: r.integrity,
                relationship: r.relationship,
                compliance: r.compliance,
                reputation: r.reputation,
                performance: performance,
                insights: insights
            };
        }

