        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var titleKey = 'round_' + (idx + 1) + '_title';
                var descKey = 'round_' + (idx + 1) + '_desc';
                var translated = t(titleKey);
                var titleText = (translated !== titleKey) ? translated : round.title;
                var descText = t(descKey);
                if (descText === descKey) descText = round.description;
                briefEl.innerHTML = '<strong>' + titleText + '</strong><br><br>' + descText;
            }

            var panel = document.getElementById('decisionsPanel');
            if (panel) {
                var html = '';
                for (var i = 0; i < round.decisions.length; i++) {
                    var dec = round.decisions[i];
                    var labelText = t(dec.label);
                    if (labelText === dec.label) labelText = dec.label;
                    html += '<div class="washguard-sim-decision-group">';
                    html += '<label for="decision_' + dec.id + '">' + labelText + '</label>';
                    html += '<select id="decision_' + dec.id + '">';
                    for (var j = 0; j < dec.options.length; j++) {
                        var opt = dec.options[j];
                        var optText = t(opt.text);
                        if (optText === opt.text) optText = opt.text;
                        html += '<option value="' + opt.value + '">' + opt.value + ': ' + optText + '</option>';
                    }
                    html += '</select></div>';
                }
                panel.innerHTML = html;
            }

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            var eventChoices = document.getElementById('eventChoices');
            if (eventPanel && round.event) {
                eventPanel.style.display = 'block';
                var evtTranslated = t(round.event.text);
                if (evtTranslated === round.event.text) evtTranslated = round.event.text;
                if (eventText) eventText.innerHTML = evtTranslated;
                if (eventChoices) {
                    var ehtml = '';
                    for (var e = 0; e < round.event.choices.length; e++) {
                        var ch = round.event.choices[e];
                        var chText = t(ch.text);
                        if (chText === ch.text) chText = ch.text;
                        ehtml += '<label><input type="radio" name="eventChoice" value="' + ch.value + '"' + (e === 0 ? ' checked' : '') + '> ' + chText + '</label>';
                    }
                    eventChoices.innerHTML = ehtml;
                }
            } else if (eventPanel) {
                eventPanel.style.display = 'none';
            }
        }

